// A question may belong to both banks; pharmacology-only entries remain in Drug Center.
Object.assign(TRAINING_TOPICS,{allergy:'Allergic reaction / anaphylaxis',nausea:'Nausea / vomiting',temperature:'Temperature emergencies',perfusion:'Hypoperfusion / sepsis',toxicology:'Overdose / poisoning',tachycardia:'Tachycardia',bradycardia:'Bradycardia',chf:'CHF / pulmonary edema',arrest:'Cardiac arrest / post-arrest',trauma:'Traumatic injury',burns:'Burns / smoke inhalation',environment:'Bites / drowning / dive',obstetric:'Obstetric emergencies',sedation:'Procedural sedation'});
const DRUG_QUESTION_TYPES={all:'All question types',dose:'Dose & repeat instructions',indication:'Indications & medication role',safety:'Precautions & monitoring',preparation:'Routes & preparation',pharmacology:'Class & action'};
for(const q of QUESTION_BANK){q.banks=q.drug?['protocol','drug']:['protocol'];q.kind= /dose|pedmax|repeat|keppra|aspirin|seiz-iv|seiz-im/.test(q.id)?'dose':/route|diluent|duration|prep|flow|mist|strength/.test(q.id)?'preparation':/caution|contra|effect/.test(q.id)?'safety':/class/.test(q.id)?'pharmacology':'indication';}
// Move existing protocol facts into their matching medication filters without copying them.
for(const [ids,drug] of [[['acs-aspirin'],'aspirin'],[['acs-analgesic'],'fentanyl'],[['diab-oral'],'oral-glucose'],[['diab-d10','diab-endpoint'],'dextrose'],[['seiz-iv','seiz-im','seiz-repeat'],'midazolam'],[['seiz-keppra','seiz-pedcontrol'],'levetiracetam']]){for(const id of ids){const q=QUESTION_BANK.find(x=>x.id===id);q.drug=drug;q.banks=['protocol','drug'];}}
function bankQuestion(id,topic,drug,page,kind,question,blank,answer,distractors,explanation,drugOnly=false){addQuestion(id,topic,drug,page,question,blank,answer,distractors,explanation);Object.assign(QUESTION_BANK[QUESTION_BANK.length-1],{kind,banks:drugOnly?['drug']:drug?['protocol','drug']:['protocol']});}
function protocolFact(id,topic,drug,page,kind,context,label,answer,distractors,note){bankQuestion(id,topic,drug,page,kind,`${context}: what is the ${label}?`,`${context}: the ${label} is ___.`,answer,distractors,note);}
